<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Request software | AROSOFT Labs</title><style>body{font:15px/1.6 system-ui;color:#142941;max-width:800px;margin:auto;padding:25px}form{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}label{display:flex;flex-direction:column;gap:5px}input,select,textarea{padding:11px;border:1px solid #ccd6e1;border-radius:8px;font:inherit}.wide{grid-column:1/-1}button{padding:13px 22px;border:0;border-radius:8px;background:#245bb6;color:white;font-weight:700}@media(max-width:600px){form{grid-template-columns:1fr}.wide{grid-column:auto}}</style></head><body><a href="/">← AROSOFT Labs</a><h1>Request a software solution</h1><p>Tell us what you need. Our team will review your requirements.</p>@if(session('request_reference'))<p role="status">Request received. Your reference is <strong>{{ session('request_reference') }}</strong>.</p>@endif@if($errors->any())<div role="alert"><strong>Please correct:</strong><ul>@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div>@endif<form method="post" action="{{ route('labs.request.store') }}">@csrf<label>Your name<input name="contact_name" required value="{{ old('contact_name') }}"></label><label>Email<input name="email" type="email" required value="{{ old('email') }}"></label><label>Phone<input name="phone" value="{{ old('phone') }}"></label><label>Organization<input name="organization" value="{{ old('organization') }}"></label><label>Project type<select name="request_type" required><option value="">Choose</option>@foreach(['website'=>'Website','ecommerce'=>'E-commerce','web_system'=>'Web system','mobile'=>'Mobile application','desktop'=>'Desktop software','integration'=>'Integration','other'=>'Other'] as $key=>$value)<option value="{{ $key }}" @selected(old('request_type')===$key)>{{ $value }}</option>@endforeach</select></label><label>Budget range<input name="budget_range" value="{{ o